// Shipping queries Orders' tables through the shared database
public sealed class LabelJob(ShopDb db)
{
    public Task<List<Label>> RunAsync(CancellationToken ct) =>
        db.Orders
            .Where(o => o.Status == "paid" && o.ShippedAt == null)
            .Select(o => new Label(o.Id, o.CustomerName, o.Street, o.City))
            .ToListAsync(ct);
}
// Orders renames a status or splits CustomerName: this breaks at
// runtime, and only a coordinated release of both services fixes it

// Orders publishes this contract and promises to keep it stable
public sealed record OrderPaid(Guid OrderId, string Recipient, Address ShipTo);

// Shipping keeps what it needs, in tables only Shipping can touch
public sealed class OnOrderPaid(ShippingDb db)
{
    public async Task HandleAsync(OrderPaid e, CancellationToken ct)
    {
        db.Shipments.Add(new Shipment(e.OrderId, e.Recipient, e.ShipTo));
        await db.SaveChangesAsync(ct);
    }
}

public sealed class LabelJob(ShippingDb db)
{
    public Task<List<Shipment>> PendingAsync(CancellationToken ct) =>
        db.Shipments.Where(s => s.ShippedAt == null).ToListAsync(ct);
}
